CREATE FUNCTION public.enforce_enrollment_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.user_id<>OLD.user_id OR NEW.course_id<>OLD.course_id THEN RAISE EXCEPTION 'Enrollment identity cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_enrollment_identity BEFORE UPDATE ON public.enrollments FOR EACH ROW EXECUTE FUNCTION public.enforce_enrollment_identity();
CREATE POLICY "own published free course enroll" ON public.enrollments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND progress=0 AND last_lesson=0 AND EXISTS(SELECT 1 FROM public.courses c WHERE c.id::text=course_id AND c.price=0 AND c.status='published') AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.account_status='active'));
CREATE POLICY "enrolled course read" ON public.courses FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.enrollments e WHERE e.user_id=auth.uid() AND e.course_id=courses.id::text));